export type ReceiptTranslationKey = keyof typeof RECEIPT_TRANSLATIONS.en;

export function getReceiptTranslation(lang: string) {
  // Check if lang exists in mapping, otherwise default to 'en'
  const language = (lang in RECEIPT_TRANSLATIONS ? lang : "en") as keyof typeof RECEIPT_TRANSLATIONS;
  return RECEIPT_TRANSLATIONS[language];
}

export function getDpdpaRights(lang: string): string[] {
  const t = getReceiptTranslation(lang);
  return [...t.dpdpaRights];
}

