/**
 * Converts ASCII digits in a string to native numerals based on language.
 * Only affects digits 0-9.
 */
export function localizeDigits(str: string, lang: string): string {
  if (!str) return str;
  // If language isn't in our map, return original string (English/ASCII)
  if (!(lang in DIGIT_MAPS)) return str;

  const digits = DIGIT_MAPS[lang];
  return str.replace(/[0-9]/g, (d) => digits[parseInt(d)]);
}
